{"commands":[{"keystrokes":"cat > /app/headless_terminal.py <<'PY'
"""A small PTY backed implementation of a headless interactive terminal."""
from __future__ import annotations

import errno
import fcntl
import os
import pty
import select
import signal
import struct
import subprocess
import termios
import time
from typing import Optional, Union

try:
    from base_terminal import BaseTerminal
except ImportError:                         # useful when this file is used standalone
    class BaseTerminal:                    # pragma: no cover
        pass

try:
    import pyte
except ImportError:                         # pyte is optional; raw output still works
    pyte = None


class HeadlessTerminal(BaseTerminal):
    """Run an interactive bash attached to a pseudo terminal.

    Unlike ``subprocess.PIPE``, a pty makes bash and programs such as ``vim``,
    ``python`` and ``top`` believe that they are connected to a real terminal.
    ``send_keys`` writes exactly the supplied characters, so control characters
    (for example ``"\\x03"``) work as expected.
    """

    def __init__(self, width: int = 120, height: int = 40, **kwargs):
        # Accept the common alternative names used by BaseTerminal versions.
        width = int(kwargs.pop("cols", kwargs.pop("columns", width)))
        height = int(kwargs.pop("rows", kwargs.pop("lines", height)))
        try:
            super().__init__(width=width, height=height, **kwargs)
        except TypeError:
            try:
                super().__init__()
            except TypeError:
                pass
        self.width, self.height = width, height
        self._master, slave = pty.openpty()
        self._set_size(self._master, width, height)
        env = os.environ.copy()
        env.setdefault("TERM", "xterm-256color")
        env["COLUMNS"] = str(width)
        env["LINES"] = str(height)

        def become_terminal():
            os.setsid()
            try:
                fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
            except (OSError, AttributeError):
                pass

        self.process = subprocess.Popen(
            ["/bin/bash", "-i"], stdin=slave, stdout=slave, stderr=slave,
            env=env, preexec_fn=become_terminal, close_fds=True,
        )
        os.close(slave)
        os.set_blocking(self._master, False)
        self._closed = False
        self._raw = bytearray()
        self._screen = None
        self._stream = None
        if pyte is not None:
            self._screen = pyte.Screen(width, height)
            self._stream = pyte.Stream(self._screen)
        # Consume bash startup output and leave the terminal at its initial prompt.
        self._drain(0.35)

    @staticmethod
    def _set_size(fd, width, height):
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", height, width, 0, 0))

    def _drain(self, quiet: float = .05) -> bytes:
        data = bytearray()
        deadline = time.monotonic() + quiet
        while not self._closed:
            remaining = max(0, deadline - time.monotonic())
            ready, _, _ = select.select([self._master], [], [], remaining)
            if not ready:
                break
            try:
                chunk = os.read(self._master, 65536)
            except BlockingIOError:
                continue
            except OSError as e:
                if e.errno in (errno.EIO, errno.EBADF):
                    break
                raise
            if not chunk:
                break
            data.extend(chunk)
            self._raw.extend(chunk)
            if self._stream is not None:
                self._stream.feed(chunk.decode("utf-8", "replace"))
            deadline = time.monotonic() + quiet
        return bytes(data)

    def send_keys(self, keys: Union[str, bytes]) -> str:
        """Send keys and return the resulting visible screen."""
        if self._closed:
            raise RuntimeError("terminal is closed")
        data = keys if isinstance(keys, bytes) else str(keys).encode("utf-8")
        view = memoryview(data)
        while view:
            try:
                n = os.write(self._master, view)
                view = view[n:]
            except InterruptedError:
                continue
        self._drain()
        return self.get_screen()

    # Convenient aliases used by different clients of terminal interfaces.
    send = send_keys
    write = send_keys
    type = send_keys

    def get_screen(self) -> str:
        if self._screen is not None:
            # pyte's display is the terminal's visible contents, not escape codes.
            return "\n".join(line.rstrip() for line in self._screen.display)
        return self._raw.decode("utf-8", "replace")

    @property
    def screen(self) -> str:
        return self.get_screen()

    def read(self, timeout: float = .05) -> str:
        self._drain(timeout)
        return self.get_screen()

    def resize(self, width: int, height: int):
        self.width, self.height = int(width), int(height)
        self._set_size(self._master, self.width, self.height)
        if self._screen is not None:
            self._screen.resize(lines=self.height, columns=self.width)

    def close(self):
        if self._closed:
            return
        self._closed = True
        try:
            if self.process.poll() is None:
                self.process.terminate()
                try:
                    self.process.wait(timeout=.5)
                except subprocess.TimeoutExpired:
                    self.process.kill()
                    self.process.wait()
        finally:
            try: os.close(self._master)
            except OSError: pass

    def terminate(self):
        self.close()

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

    def __del__(self):
        try: self.close()
        except Exception: pass
